--Consignees with updated SalesrepIDs from 7-30-2021 update script
-- compared to what is on the Order Header for these Consignees.

SELECT DISTINCT * FROM (

SELECT 
	OH.TRANSACTIONDATE,
	OH.TRANSACTIONNUMBER,
	OH.STAGE, 
	LEFT(FF.FLAGDESCRIPTION,CHARINDEX(' -',FF.FLAGDESCRIPTION)) AS STAGETEXT, 
	CUST.IDENTITYID AS CUSTOMERID, CUST.NAME AS CUSTOMERNAME, 
	CONS.IDENTITYID AS CONSIGNEEID, CONS.NAME AS CONSIGNEENAME, 
	ICONS.USERDEFINEDCODE_12 AS TERRITORY, 
	PART.IDENTITYID AS OHREP, 
	PART.NAME AS OHREPNAME, 
	IPART.IDENTITYID AS CONREP, 
	IPART.NAME AS CONREPNAME--, 	KPART.IDENTITYID AS KEYREP, 	KPART.NAME AS KEYREPNAME 

FROM OMTRANSACTIONHEADER OH (NOLOCK) 
JOIN IDMASTER CUST (NOLOCK) ON CUST.ROWID = OH.R_CUSTOMER 
JOIN IDMASTER CONS (NOLOCK) ON CONS.ROWID = OH.R_SHIPPER 
JOIN IDCONSIGNEE ICONS (NOLOCK) ON ICONS.R_IDENTITY = OH.R_SHIPPER 
JOIN IDMASTER PART (NOLOCK) ON PART.ROWID = OH.R_SALESPERSON_1 
JOIN IDMASTER IPART (NOLOCK) ON IPART.ROWID = ICONS.R_PARTICIPANT 
--LEFT JOIN IDRELATIONSHIPLINKS LCUST (NOLOCK) ON LCUST.R_IDMASTER = OH.R_CUSTOMER AND LCUST.IDMASTERTYPE = '01' AND LCUST.IDMEMBERTYPE = '14' 
--LEFT JOIN IDMASTER KPART (NOLOCK) ON KPART.ROWID = LCUST.R_IDMEMBER 
JOIN ABFLAGFIELD FF (NOLOCK) ON FF.FIELDNAME LIKE 'STAGE' AND LEFT(FF.TABLENAME,2) = 'OM' AND FF.FLAGVALUE = OH.STAGE
